        self.status_code = status_code
        self._json = json_data
        self.headers = {}
        self.text = str(json_data)

    def json(self):
        return self._json


class DummyHttpxClient:
    def request(self, *args, **kwargs):
        # Ignore all args/kwargs, always return a 409 response
        return DummyResponse(409, {"error": "conflict"})


class DummyWrapper:
    def __init__(self):
        self.httpx_client = DummyHttpxClient()


def test_create_raises_conflict_error():
    client = RawModelsClient(client_wrapper=DummyWrapper())
    with pytest.raises(ConflictError):
